examples.template:
@OptIn(ExperimentalMonarchApi::class)
MonarchThreadPanel(
    replies = replies,
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 6),
    key = { it.id },
    time = { it.time },
    following = following,
    authorId = { it.author },
    now = {{now|millis}},
    onClose = {},
    onFollowingChange = { following = it },
    onRepliesSeen = { _ -> },
    root = {
        MonarchMessageRow(author = MonarchMessageRowAuthor({{root.name}}), time = {{root.time|millis}}, now = {{now|millis}}) {
            MonarchText({{root.body}})
        }
    },
    composer = {
        MonarchMessageComposer(
            label = {{placeholder}},
            state = draft,
            placeholder = {{placeholder}},
            onSend = { message ->
                replies += Reply("r${replies.size + 1}", "You", message.text, {{now|millis}})
            },
        )
    },
) { reply, context ->
    MonarchMessageRow(
        author = MonarchMessageRowAuthor(reply.author),
        time = reply.time,
        now = {{now|millis}},
        grouped = context.grouped,
    ) { MonarchText(reply.text) }
}

